// The body figure the coverage sheet shades is src/data/body.json — MuscleMap's male front
// and back outlines, generated by scripts/build-body.mjs and never hand-edited. This file
// holds no import so the script can read it under plain Node.

// Which drawn parts each muscle group lights. Anything not named here is silhouette — the
// head, hands, forearms and shins carry no group, because `muscles.js` counts none.
export const PARTS = {
  Quads: ['quadriceps'],
  'Hamstrings & glutes': ['hamstring', 'gluteal', 'adductors'],
  Chest: ['chest'],
  Back: ['upperBack', 'lowerBack', 'trapezius', 'rhomboids'],
  Shoulders: ['deltoids', 'rotatorCuff'],
  Triceps: ['triceps'],
  Biceps: ['biceps'],
  Calves: ['calves'],
  Core: ['abs', 'obliques'],
}
